            }

override fun resolveDue(): Int {
    val due = payments.findDueForInquiry(clock.instant(), BATCH_SIZE)
    due.forEach { p ->
        runCatching { resolve(p) }
            .onFailure { log.warn(it) { "결제 재조회 실패: orderNo=${p.orderNo}" } }
    }
    return due.size
}

