fun lastClosedPeriod(today: LocalDate): SettlementPeriod = when (this) {
    WEEKLY -> {
        val end = today.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY))
        SettlementPeriod(end.minusWeeks(1), end)
    }
    MONTHLY -> {
        val end = today.withDayOfMonth(1)
        SettlementPeriod(end.minusMonths(1), end)
    }
}

    fun of(netSales: Long, rateBp: Int): Long {
        require(netSales >= 0) { "순매출은 음수일 수 없다" }
        require(rateBp in 0..10_000) { "수수료율은 0~10000bp" }
        return BigDecimal.valueOf(netSales).multiply(BigDecimal.valueOf(rateBp.toLong()))
            .divide(BP_SCALE, 0, RoundingMode.HALF_UP)
            .longValueExact()
    }
}

